-- Datos de ejemplo para el dashboard de rotación de personal (RF-75, KAN-95).
-- Requiere init.sql y seed.sql de EmployeeService (cargos, áreas y estados). Después ejecute el seed-rotacion.sql
-- de CompensationService, que registra las bajas de estas personas con su causal.
-- Se puede ejecutar varias veces: lo que ya existe no se duplica.
--   cat backend/EmployeeService/db/seed-rotacion.sql | docker exec -i rrhh-postgres psql -U adminRRHH -d EmployeeDB
--
-- Qué queda cargado:
--   Sucursal Calacoto (tercera sucursal) y 65 colaboradores en Sopocachi, Miraflores y Calacoto.
--   46 ingresaron antes de los últimos 12 meses; 19 ingresaron mes a mes durante ese periodo.
--   10 están dados de baja (estado BAJA); su causal y fecha de retiro están en CompensationDB.
--   Las fechas de los últimos 12 meses son relativas al mes actual de La Paz, así el dashboard siempre tiene datos.
BEGIN;
INSERT INTO SUCURSALES (id_sucursal, codigo_sucursal, nombre, direccion, ciudad) VALUES
  ('f0000000-0000-4000-8095-000000000001', 'SUC-CAL', 'Calacoto', 'Av. Ballivián 1100', 'La Paz')
ON CONFLICT DO NOTHING;
WITH b AS (SELECT date_trunc('month', timezone('America/La_Paz', now()))::date AS mes)
INSERT INTO EMPLEADOS (id_empleado, numero_documento, nombres, primer_apellido, segundo_apellido, fecha_nacimiento, genero, telefono_celular, correo_personal, direccion_domicilio, fecha_ingreso, id_cargo_actual, id_sucursal_actual, id_estado_empleado)
